37		nodes          map[int]*Node // ID -> Node
38		entryPoint     int           // ID of the top-level entry point
39		maxLayer       int           // Maximum layer in the graph
40		efConstruction int           // Size of dynamic candidate list during construction
41		efSearch       int           // Size of dynamic candidate list during search
