228	// Clear removes all nodes from the index
229	func (h *Index) Clear() {
230		h.mu.Lock()
231		defer h.mu.Unlock()
232	
233		h.nodes = make(map[int]*Node)
234		h.entryPoint = -1
235		h.maxLayer = -1
236		h.nodeCount = 0
237	}
